#!/usr/bin/env node
/**
 * Deprecated: sync normalized SHEIN link-management JSON into Lark Base.
 *
 * Input files are generated by scripts/fetch_shein_links.mjs.
 * This script creates/maintains dedicated link-management tables and writes
 * records idempotently by the "唯一键" field.
 *
 * The Feishu/Lark link-management feature has been retired. Production link
 * data now flows to local JSON/PostgreSQL/BI only. Keep this file for
 * emergency historical migration, but refuse to write unless explicitly
 * enabled with SHEIN_ENABLE_DEPRECATED_LARK_LINK_SYNC=1.
 */
