function parseArgs(argv) {
  const args = {
    group: 'DSY',
    stores: null,
    date: null,
    files: [],
    ensureOnly: false,
    viewsOnly: false,
    syncDashboard: false,
    setupDashboard: false,
    cleanDashboard: false,
    skipLinkMainUpdates: false,
    maxActionsPerStore: 8,
    actionsOnly: false,
    suggestionsOnly: false,
    hideStaleActions: false,
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--date') args.date = argv[++i];
    else if (a === '--group') args.group = argv[++i].toUpperCase();
    else if (a === '--stores') args.stores = argv[++i].split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
    else if (a === '--store') args.stores = [argv[++i].trim().toUpperCase()];
    else if (a === '--file') args.files.push(path.resolve(argv[++i]));
    else if (a === '--ensure-only') args.ensureOnly = true;
    else if (a === '--views-only') args.viewsOnly = true;
    else if (a === '--no-dashboard-data') args.syncDashboard = false;
    else if (a === '--dashboard') args.setupDashboard = true;
    else if (a === '--no-dashboard') args.setupDashboard = false;
    else if (a === '--clean-dashboard') args.cleanDashboard = true;
    else if (a === '--skip-link-main-updates') args.skipLinkMainUpdates = true;
    else if (a === '--max-actions-per-store') args.maxActionsPerStore = Math.max(0, Number(argv[++i] || 8));
    else if (a === '--actions-only') args.actionsOnly = true;
    else if (a === '--suggestions-only') args.suggestionsOnly = true;
    else if (a === '--hide-stale-actions') args.hideStaleActions = true;
  }
  if (!args.date && !args.files.length && !args.ensureOnly && !args.viewsOnly) throw new Error('Use --date, --file, --ensure-only, or --views-only');
  if (args.viewsOnly && !args.date) throw new Error('Use --date with --views-only');
  return args;
}

