function metric(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function indexKey(storeKey, id) {
  return `${storeKey || ''}__${id || ''}`;
}

function buildActionContext(objects, suppressedStandards = new Set()) {
  const perfByStoreSkc = new Map();
  const invByStoreSkc = new Map();
  const covByStoreSku = new Map();
  const standardStats = new Map();
  const getStats = standardGoodsSn => {
    const key = standardGoodsSn || '';
    if (!standardStats.has(key)) {
      standardStats.set(key, {
        stores: new Set(),
        onShelfStores: new Set(),
        onShelfCount: 0,
        c7SaleCnt: 0,
        c30SaleCnt: 0,
        c30EpsUv: 0,
      });
    }
    return standardStats.get(key);
  };
  for (const {obj} of objects) {
    const storeKey = obj.store?.storeKey || '';
    for (const row of obj.coverageRows || []) {
      covByStoreSku.set(indexKey(row.storeKey || storeKey, row.standardGoodsSn), row);
      if (!row.standardGoodsSn) continue;
      const stats = getStats(row.standardGoodsSn);
      stats.stores.add(row.storeKey || storeKey);
      if (row.hasOnShelfLink) stats.onShelfStores.add(row.storeKey || storeKey);
      stats.onShelfCount += metric(row.onShelfCount, 0);
    }
    for (const row of obj.performanceRows || []) {
      perfByStoreSkc.set(indexKey(row.storeKey || storeKey, row.skc), row);
      if (!row.standardGoodsSn) continue;
      const stats = getStats(row.standardGoodsSn);
      stats.c7SaleCnt += metric(row.c7SaleCnt, 0);
      stats.c30SaleCnt += metric(row.c30SaleCnt, 0);
      stats.c30EpsUv += metric(row.c30EpsUv, 0);
    }
    for (const row of obj.inventoryRows || []) {
      invByStoreSkc.set(indexKey(row.storeKey || storeKey, row.skc), row);
    }
  }
  return {perfByStoreSkc, invByStoreSkc, covByStoreSku, standardStats, suppressedStandards};
}

function actionPerf(row, ctx) {
  return ctx.perfByStoreSkc.get(indexKey(row.storeKey, row.skc)) || {};
}

function actionInventory(row, ctx) {
  return ctx.invByStoreSkc.get(indexKey(row.storeKey, row.skc)) || {};
}

function actionCoverage(row, ctx) {
  return ctx.covByStoreSku.get(indexKey(row.storeKey, row.standardGoodsSn)) || {};
}

function actionStandardStats(row, ctx) {
  return ctx.standardStats.get(row.standardGoodsSn || '') || {
    stores: new Set(),
    onShelfStores: new Set(),
    onShelfCount: 0,
    c7SaleCnt: 0,
    c30SaleCnt: 0,
    c30EpsUv: 0,
  };
}

function normalizeSuggestionRows(objects, suppressedStandards = new Set()) {
  for (const {obj} of objects) {
    obj.suggestionRows = (obj.suggestionRows || [])
      .filter(row => !['HARD_DEAD_LINK', 'DISPLAY_STOCK_LOW'].includes(row.ruleCode) && !suppressedStandards.has(row.standardGoodsSn))
      .map(row => ({
        ...row,
        allStoresNoOnShelfNoReminder: suppressedStandards.has(row.standardGoodsSn),
      }));
  }
}

function actionCategory(row) {
  const code = row.ruleCode || '';
  if (code === 'COVERAGE_MISSING') return '补上架链接';
  if (code === 'WAIT_SHELF_BLOCKED') return row.suggestionType?.includes('证书') ? '补证书/资料' : '处理待上架卡点';
  if (code === 'DISPLAY_STOCK_LOW') return '调高展示库存';
  if (code === 'C30_ZERO_SALE') return '淘汰候选复核';
  if (code === 'TRAFFIC_NO_SALE') return '优化转化';
  if (code === 'HIGH_EXPOSURE_LOW_CLICK') return '优化点击';
  if (code === 'HIGH_VISITOR_LOW_PAY') return '优化支付转化';
  if (code === 'SALE_DROP_7D' || code === 'EXPOSURE_DROP_7D') return '修复下滑';
  return '参考观察';
}
function prioritySort(row) {
  const p = row.priority || '';
  const base = p === '高' ? 10 : p === '中' ? 30 : 60;
  const codeRank = {
    WAIT_SHELF_BLOCKED: 1,
    COVERAGE_MISSING: 2,
    DISPLAY_STOCK_LOW: 3,
    TRAFFIC_NO_SALE: 4,
    HIGH_EXPOSURE_LOW_CLICK: 5,
    HIGH_VISITOR_LOW_PAY: 6,
    SALE_DROP_7D: 7,
    EXPOSURE_DROP_7D: 8,
    C30_ZERO_SALE: 9,
  }[row.ruleCode] || 90;
  return base + codeRank;
}
function oneLineAction(row) {
  const target = [row.storeKey, row.standardGoodsSn, row.skc].filter(Boolean).join(' / ');
  const category = actionCategory(row);
  if (row.ruleCode === 'WAIT_SHELF_BLOCKED') return `${category}：${target}`;
  if (row.ruleCode === 'COVERAGE_MISSING') return `补 1 条可上架链接：${target}`;
  if (row.ruleCode === 'DISPLAY_STOCK_LOW') return `把 SHEIN 展示库存调高：${target}`;
  if (row.ruleCode === 'C30_ZERO_SALE') return `30天无销量，复核是否替换/下架：${target}`;
  return `${category}：${target}`;
}
function includeInActionList(row, ctx) {
  const code = row.ruleCode || '';
  if (['SHEIN_FLOW_DIAGNOSE', 'HARD_DEAD_LINK', 'DUPLICATE_WEAK_LINK', 'DISPLAY_STOCK_LOW'].includes(code)) return false;
  if (row.allStoresNoOnShelfNoReminder || ctx.suppressedStandards.has(row.standardGoodsSn)) return false;

  const perf = actionPerf(row, ctx);
  const inv = actionInventory(row, ctx);
  const cov = actionCoverage(row, ctx);
  const stats = actionStandardStats(row, ctx);

  if (code === 'WAIT_SHELF_BLOCKED') return true;

  if (code === 'COVERAGE_MISSING') {
    return stats.onShelfStores.size > 0
      && (stats.c7SaleCnt >= 3 || stats.c30SaleCnt >= 10 || (stats.onShelfStores.size >= 5 && stats.c30SaleCnt >= 5));
  }

  if (code === 'DISPLAY_STOCK_LOW') {
    const recentSale = Math.max(metric(perf.c7SaleCnt, 0), metric(inv.c7dSaleCnt, 0));
    const stock = metric(inv.platformDisplayStock, Number.POSITIVE_INFINITY);
    const saleDays = metric(inv.minStockSaleDays, Number.POSITIVE_INFINITY);
    return recentSale >= 2 && (stock <= 10 || saleDays <= 2);
  }

  if (code === 'TRAFFIC_NO_SALE') {
    return metric(perf.c30SaleCnt, 0) === 0 && metric(perf.c30EpsUv, 0) >= 1000;
  }

  if (code === 'HIGH_EXPOSURE_LOW_CLICK') {
    return metric(perf.c7EpsUv, 0) >= 500 && metric(perf.c7ClickRate, 1) < 0.01;
  }

  if (code === 'HIGH_VISITOR_LOW_PAY') {
    return metric(perf.c7GoodsUv, 0) >= 100 && metric(perf.c7PayRate, 1) < 0.01;
  }

  if (code === 'SALE_DROP_7D') {
    return metric(perf.prev7SaleCnt, 0) >= 5 && metric(perf.c7SaleCnt, 0) <= metric(perf.prev7SaleCnt, 0) * 0.5;
  }

  if (code === 'EXPOSURE_DROP_7D') {
    return metric(perf.prev7EpsUv, 0) >= 500 && metric(perf.c7EpsUv, 0) <= metric(perf.prev7EpsUv, 0) * 0.5;
  }

  if (code === 'C30_ZERO_SALE') {
    return metric(perf.c30SaleCnt, 0) === 0 && metric(perf.c30EpsUv, 0) >= 500 && metric(cov.onShelfCount, 0) > 1;
  }

  return false;
}

function actionSeverity(row, ctx) {
  const perf = actionPerf(row, ctx);
  const inv = actionInventory(row, ctx);
  const stats = actionStandardStats(row, ctx);
  if (row.ruleCode === 'WAIT_SHELF_BLOCKED') return 100000;
  if (row.ruleCode === 'COVERAGE_MISSING') return stats.c30SaleCnt * 100 + stats.c7SaleCnt * 20 + stats.onShelfStores.size;
  if (row.ruleCode === 'DISPLAY_STOCK_LOW') return Math.max(metric(perf.c7SaleCnt, 0), metric(inv.c7dSaleCnt, 0)) * 100 - metric(inv.platformDisplayStock, 0);
  if (row.ruleCode === 'TRAFFIC_NO_SALE') return metric(perf.c30EpsUv, 0);
  if (row.ruleCode === 'HIGH_EXPOSURE_LOW_CLICK') return metric(perf.c7EpsUv, 0);
  if (row.ruleCode === 'HIGH_VISITOR_LOW_PAY') return metric(perf.c7GoodsUv, 0);
  if (row.ruleCode === 'SALE_DROP_7D') return metric(perf.prev7SaleCnt, 0) - metric(perf.c7SaleCnt, 0);
  if (row.ruleCode === 'EXPOSURE_DROP_7D') return metric(perf.prev7EpsUv, 0) - metric(perf.c7EpsUv, 0);
  if (row.ruleCode === 'C30_ZERO_SALE') return metric(perf.c30EpsUv, 0);
  return 0;
}

function compareActionSuggestions(a, b, ctx) {
  return prioritySort(a) - prioritySort(b)
    || actionSeverity(b, ctx) - actionSeverity(a, ctx)
    || String(a.storeKey || '').localeCompare(String(b.storeKey || ''))
    || String(a.standardGoodsSn || '').localeCompare(String(b.standardGoodsSn || ''), 'zh-Hans-CN')
    || String(a.skc || '').localeCompare(String(b.skc || ''));
}

function capStoreActions(rows, maxActionsPerStore = 0) {
  if (!maxActionsPerStore || maxActionsPerStore <= 0) return rows;
  return rows.slice(0, maxActionsPerStore);
}

function markDailyFocus(rows, maxFocusPerStore = 3) {
  rows.forEach((row, index) => {
    row['是否今日重点'] = index < maxFocusPerStore;
  });
  return rows;
}
